          <span><em>\uC190\uC775\uBE44</em><b>${g.rr?"1 : "+g.rr.v+(g.rr.big?"+":""):"\u2014"}</b>${g.rr?`<small>\uBAA9\uD45C ${v(g.rr.t)} \xB7 \uC190\uC808 ${v(g.rr.s)}</small>`:""}</span>
